  tools.append(personalElement('small','EEG demo','personality-demo-badge'),headsetHelp('About personality estimates',[personalElement('p','Survey bars use answered items only, with reverse scoring where required. Unanswered dimensions are not estimated. EEG bars match recorded band powers to invented profiles whose personality scores were assigned independently. They have no demonstrated personality accuracy. Questionnaire answers are not used for the EEG match. Scores run from 1 to 5, not confidence or classification accuracy. Bar whiskers show ± one sample SD of answered items or matched synthetic profiles, not confidence intervals. The Enneagram circle shows nine separate dimension scores; connecting lines do not imply psychological relationships.')]));

  const chart=personalElement('div',undefined,'personality-comparison');personality.append(tools,chart);
  const eeg=personalElement('details',undefined,'insight-disclosure');eeg.open=true;eeg.append(personalElement('summary','EEG'));
